mapper.select:
SELECT id, group_id, user_id, mood, mood_score, note, log_date, created_at
FROM mood_log
WHERE group_id = #{groupId}
  AND log_date = #{logDate}
ORDER BY created_at ASC

SELECT id, group_id, user_id, mood, mood_score, note, log_date, created_at
FROM mood_log
WHERE group_id = #{groupId}
  AND log_date BETWEEN #{startDate} AND #{endDate}
ORDER BY log_date DESC, created_at DESC

SELECT COUNT(DISTINCT log_date)
FROM mood_log
WHERE group_id = #{groupId}
  AND log_date BETWEEN #{startDate} AND #{endDate}
